/// Punctuation marks (all ASCII).
pub static PUNCTUATION_MARKS: [char; 33] = [
    ',', ';', ':', '.', '"', '\'', '!', '?', ' ', '<', '>', '=', '+', '-', '*', '/', '\\', '_', '~', '`', '@', '#', '$', '%',
    '^', '&', '(', ')', '{', '}', '[', ']', '|',
];

/// Mark family rows, indexed by `Mark`; '_' marks a missing slot.
pub static FAMILY_A: [char; 5] = ['a', 'â', 'ă', '_', '_'];
pub static FAMILY_D: [char; 5] = ['d', '_', '_', '_', 'đ'];
pub static FAMILY_E: [char; 5] = ['e', 'ê', '_', '_', '_'];
pub static FAMILY_O: [char; 5] = ['o', 'ô', '_', 'ơ', '_'];
pub static FAMILY_U: [char; 5] = ['u', '_', '_', 'ư', '_'];

/// Mark family of a character, the C++ kMarkFamilies table.
pub fn mark_family(c: char) -> Option<&'static [char]> {
    match c {
        'a' | 'â' | 'ă' => Some(&FAMILY_A),
        'd' | 'đ' => Some(&FAMILY_D),
        'e' | 'ê' => Some(&FAMILY_E),
        'o' | 'ô' | 'ơ' => Some(&FAMILY_O),
        'u' | 'ư' => Some(&FAMILY_U),
        _ => None,
    }
}

